param([string]$OutFile,[int]$Seconds=30)
Write-Host "Measuring $Seconds seconds...";$a=Get-Process|Select-Object Id,ProcessName,CPU,WorkingSet64;Start-Sleep -Seconds $Seconds;$b=Get-Process|Select-Object Id,ProcessName,CPU,WorkingSet64;$r=foreach($x in $b){$old=$a|Where-Object Id -eq $x.Id|Select-Object -First 1;if($old){[pscustomobject]@{Process=$x.ProcessName;CPU_s=[math]::Round(($x.CPU-$old.CPU),2);RAM_MB=[math]::Round($x.WorkingSet64/1MB,0)}}};$top=$r|Sort-Object CPU_s -Descending|Select-Object -First 15;@('WINTOOL - BACKGROUND LOAD','')+($top|Format-Table -AutoSize|Out-String)+@('','Read-only. WinTool does not change priorities.')|Set-Content $OutFile -Encoding UTF8
